insert into public.class_bookings(id,tenant_id,session_id,member_id,status,marked_at)select pg_temp.u(900+n),pg_temp.u(1),pg_temp.u(702),pg_temp.u(n),case when n=108 then 'attended'::public.booking_status when n=109 then 'no_show'::public.booking_status else 'booked'::public.booking_status end,case when n in(108,109)then now()else null end from generate_series(100,109)n;
insert into public.notifications(id,tenant_id,member_id,channel,category,template_key,related_type,related_id,status,scheduled_for,dedupe_key,payload)values(pg_temp.u(990),pg_temp.u(1),pg_temp.u(101),'in_app','class_update','class_session_cancelled','class_session',pg_temp.u(702),'scheduled',now(),'class-cancelled:'||pg_temp.u(702)||':'||pg_temp.u(101),jsonb_build_object('body','Previously queued notice','kind','fixture','sessionId',pg_temp.u(702),'reason','Previously queued'));
update public.notifications set status='sent'where id=pg_temp.u(990);
create temp table h74_existing as select to_jsonb(n)facts from public.notifications n where id=pg_temp.u(990);
select is(pg_temp.run($q$select to_jsonb(r)from public.cancel_class_session(pg_temp.u(702),'Instructor unwell')r$q$,pg_temp.sc(3))->>'error','42501','CLS cancel notice nonadmin 3');
select is(pg_temp.run($q$select to_jsonb(r)from public.cancel_class_session(pg_temp.u(702),'Instructor unwell')r$q$,pg_temp.sc(4))->>'error','42501','CLS cancel notice nonadmin 4');
select is(pg_temp.run($q$select to_jsonb(r)from public.cancel_class_session(pg_temp.u(702),'Instructor unwell')r$q$,pg_temp.sc(6))->>'error','42501','CLS cancel notice nonadmin 6');
select is(pg_temp.run($q$select to_jsonb(r)from public.cancel_class_session(pg_temp.u(702),'Instructor unwell')r$q$,(pg_temp.sc()::jsonb||jsonb_build_object('impersonation_session_id',pg_temp.u(999)))::text)->>'error','42501','CLS preview cancellation refused');
select is((select status::text from public.class_sessions where id=pg_temp.u(702)),'scheduled','CLS refusals leave session unchanged');
select is((select count(*)from public.notifications where related_id=pg_temp.u(702)),1::bigint,'CLS refusals write no notices');
insert into h74_res values('cancel',pg_temp.run($q$select to_jsonb(r)from public.cancel_class_session(pg_temp.u(702),'  Instructor unwell  ')r$q$,pg_temp.sc(2)));
select is((select v from h74_res where k='cancel'),'{"bookings_cancelled":8,"notices_written":5,"notices_withheld":3,"members_without_app":1}'::jsonb,'CLS cancellation counts include duplicate and no-app');
select is((select count(*)from public.class_bookings where session_id=pg_temp.u(702)and status='session_cancelled'and cancelled_at is not null),8::bigint,'CLS exactly booked rows session-cancelled');
select is((select status::text from public.class_bookings where session_id=pg_temp.u(702)and member_id=pg_temp.u(108)),'attended','CLS cancellation preserves attended');
select is((select status::text from public.class_bookings where session_id=pg_temp.u(702)and member_id=pg_temp.u(109)),'no_show','CLS cancellation preserves no_show');
select is((select count(*)from public.notifications where related_id=pg_temp.u(702)),5::bigint,'CLS notice persisted cardinality');
select is((select to_jsonb(n)from public.notifications n where id=pg_temp.u(990)),(select facts from h74_existing),'CLS duplicate notice immutable');
select ok(exists(select 1 from public.notifications where related_id=pg_temp.u(702)and member_id=pg_temp.u(100)and category='class_update'and channel='in_app'and status='sent'),'CLS transactional notice withdrawn both purposes');
select ok(exists(select 1 from public.notifications where related_id=pg_temp.u(702)and member_id=pg_temp.u(102)and category='class_update'and channel='in_app'and status='sent'),'CLS transactional notice no consent');
select ok(exists(select 1 from public.notifications where related_id=pg_temp.u(702)and member_id=pg_temp.u(104)and category='class_update'and channel='in_app'and status='sent'),'CLS transactional notice no app');
select is((select count(*)from public.notifications where related_id=pg_temp.u(702)and member_id=pg_temp.u(105)),0::bigint,'CLS no cancellation notice blocked');
select is((select count(*)from public.notifications where related_id=pg_temp.u(702)and member_id=pg_temp.u(106)),0::bigint,'CLS no cancellation notice cancelled');
select is((select count(*)from public.notifications where related_id=pg_temp.u(702)and member_id=pg_temp.u(107)),0::bigint,'CLS no cancellation notice erased');
select is((select count(*)from public.notifications where related_id=pg_temp.u(702)and member_id=pg_temp.u(108)),0::bigint,'CLS no cancellation notice attended');
select is((select count(*)from public.notifications where related_id=pg_temp.u(702)and member_id=pg_temp.u(109)),0::bigint,'CLS no cancellation notice no_show');
select ok(not exists(select 1 from public.notifications where related_id=pg_temp.u(702)and id<>pg_temp.u(990)and(template_key<>'class_session_cancelled'or related_type<>'class_session'or dedupe_key<>'class-cancelled:'||pg_temp.u(702)||':'||member_id or payload->>'sessionId'<>pg_temp.u(702)::text or jsonb_typeof(payload->'kind')<>'string'or nullif(payload->>'kind','')is null or payload->>'reason'<>'Instructor unwell')),'CLS notice fixed metadata and nonempty kind');
select is((select payload->>'body'from public.notifications where related_id=pg_temp.u(702)and member_id=pg_temp.u(100)),(select 'CLS Yoga on '||to_char(starts_at at time zone 'Asia/Kolkata','FMDD Mon YYYY')||' at '||lower(to_char(starts_at at time zone 'Asia/Kolkata','FMHH12:MI am'))||' has been cancelled. Reason: Instructor unwell'from public.class_sessions where id=pg_temp.u(702)),'CLS exact local cancellation body');
select ok(not exists(select 1 from public.notifications n,jsonb_object_keys(payload)k where related_id=pg_temp.u(702)and id<>pg_temp.u(990)and k not in('body','kind','sessionId','reason')),'CLS payload no extra personal fields');
select ok(exists(select 1 from public.audit_log where tenant_id=pg_temp.u(1)and record_id=pg_temp.u(702)and action='class_session.cancelled'and actor_user_id=pg_temp.u(202)and actor_role='gym_manager'and before='{"status":"scheduled"}'::jsonb and after='{"status":"cancelled","bookings_cancelled":8,"notices_written":5,"notices_withheld":3}'::jsonb and reason='Instructor unwell'),'CLS exact cancellation audit attribution counts');
select is((select count(*)from public.audit_log where tenant_id=pg_temp.u(1)and action in('class_booking.cancelled','class_booking.cancelled_by_gym')and record_id in(select id from public.class_bookings where session_id=pg_temp.u(702))),0::bigint,'CLS session cancellation has no per-booking audit');
select is(pg_temp.run($q$select to_jsonb(r)from public.cancel_class_session(pg_temp.u(702),'Again please')r$q$,pg_temp.sc())->>'error','GL111','CLS replay cancelled refusal');
select is((select count(*)from public.notifications where related_id=pg_temp.u(702)),5::bigint,'CLS replay no additional notices');
create function pg_temp.refuse_cls_notice()returns trigger language plpgsql as $$begin if new.related_id=pg_temp.u(705)then raise exception using errcode='23514',message='held notice storage refusal';end if;return new;end$$;
create trigger h74_holdout_notice_refusal before insert on public.notifications for each row execute function pg_temp.refuse_cls_notice();
